            [80] = { str = "Loot the Bundle of Wood on the ground. They are found beneath the trees #DOBundle of Wood (8)#" },
            [81] = { str = "Go to #COORD[80,56]# in Elwynn Forest. Click Rolf's corpse on the ground Murloc Foragers will cast [Drink Minor Potion] which heals themselves for 61-68 Cast [Renew] and [Power Word: Shield] then get full mana. Pull the 2 Murlocs in front of the huts, move away, then nuke one. Run away when you kill one, then kill the other Pull the 2 Murlocs in front of the huts, move away and [Polymorph] one whilst killing the other. Kill the Polymorphed one after Pool 100 Rage. Pull the 2 Murlocs in front of the huts, move away and keep [Hamstring] on one whilst killing the other. Also use [Bag of Marbles] on the one you're killing. Run away and reset the one being kited with [Hamstring] after you've killed one Pull the 2 Murlocs in front of the huts, move away and focus killing one of them. Use [Evasion] once they're both attacking you. This is a good opportunity to use [Bag of Marbles]. Run away and reset once you've killed one Pull the 2 Murlocs in front of the huts, move away and cast [Fear] on one of them constantly, and try to keep DoTs on both Pull the 2 Murlocs in front of the huts, move away and nuke one of them down fast. Use [Divine Protection] and your Heals as required. This is a good opportunity to use [Bag of Marbles]. Run away and reset once you've killed one Remember during [Divine Protection] you are unable to attack Turn in #INDiscover Rolf's Fate# Accept #GETReport to Thomas#", x = 80, y = 56, zone = "Elwynn Forest" },
